package com.autocare.controller;
import com.autocare.dto.request.VehicleRequest; import com.autocare.dto.response.VehicleResponse; import com.autocare.service.VehicleService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/vehicles") @SecurityRequirement(name="bearerAuth")
public class VehicleController { private final VehicleService vehicles; public VehicleController(VehicleService vehicles) { this.vehicles=vehicles; } @GetMapping public List<VehicleResponse> search(@RequestParam(required=false) String search) { return vehicles.search(search); } @GetMapping("/{vehicleId}") public VehicleResponse get(@PathVariable String vehicleId) { return vehicles.get(vehicleId); } @PutMapping("/{vehicleId}") public VehicleResponse update(@PathVariable String vehicleId,@Valid @RequestBody VehicleRequest request) { return vehicles.update(vehicleId,request); } }
